export function StringCatalogue({
  catalogueName = "{{catalogueName}}",
  highlightLang = "{{highlightLang}}",
  showKeys = {{showKeys}},
  accent = "{{accent}}",
}) {
  const rows = [
    { key: "save_button", en: "Save", fr: "Enregistrer", es: "Guardar" },
    { key: "cancel_button", en: "Cancel", fr: "Annuler", es: "Cancelar" },
  ];
  const langs = ["en", "fr", "es"];
  const cell = (l) => ({ padding: 6, borderBottom: "1px solid #24143014", fontSize: 11, background: l === highlightLang ? accent : "transparent", borderRadius: l === highlightLang ? 4 : 0 });
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>{catalogueName}</p>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <tbody>
          <tr><th style={{ textAlign: "left", padding: 6, fontSize: 11 }}>{showKeys && "key"}</th>{langs.map((l) => <th key={l} style={cell(l)}>{l}</th>)}</tr>
          {rows.map((r) => (
            <tr key={r.key}>
              <td style={{ textAlign: "left", padding: 6, fontSize: 11 }}>{showKeys && r.key}</td>
              {langs.map((l) => <td key={l} style={cell(l)}>{r[l]}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
